def gcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a
    

def algorithm(n,B): # n 
    a=2
    for j in range(2,B+1): 
        print(j)
        a=pow(a,j,n)
    d=gcd(a-1,n)
    if d>1 and d<n:
        return d 
    return -1

